/// Gets the General Category for a code point using two-stage trie lookup
pub fn getGeneralCategory(cp: Codepoint) GeneralCategory {
    if (cp > 0x10FFFF) return .Cn;
    const block = @as(usize, cp >> 8);
    if (block >= gc_stage1.len) return .Cn;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = gc_stage1[block] + offset;
    if (stage2_idx >= gc_stage2.len) return .Cn;
    return @enumFromInt(gc_stage2[stage2_idx]);
}
